pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 amount, uint256 duration) internal {
        vm.assume(duration <= 10 * 365 days);
        uint256 interest;
        try c.interestFor(amount, 0, duration) returns (uint256 __r) { interest = __r; } catch { return; }
        assertTrue(interest == 0);
    }

    function testFuzz_run(uint256 amount, uint256 duration) public {
        _run(amount, duration);
    }

    receive() external payable {}
}
